package com.ssafy.yumyumcoach.util;

import java.time.LocalDate;
import java.util.Scanner;
public class InputUtil { private final Scanner sc; public InputUtil(Scanner sc){this.sc=sc;} public String text(String label){while(true){System.out.print(label);String v=sc.nextLine().trim();if(!v.isEmpty())return v;System.out.println("빈 값은 입력할 수 없습니다.");}} public String optional(String label,String current){System.out.print(label+" [현재: "+current+"]: ");String v=sc.nextLine().trim();return v.isEmpty()?current:v;} public int integer(String label,int min,int max){while(true)try{int v=Integer.parseInt(text(label));if(v<min||v>max)throw new NumberFormatException();return v;}catch(NumberFormatException e){System.out.printf("%d~%d 정수를 입력하세요.%n",min,max);}} public long longValue(String label){while(true)try{return Long.parseLong(text(label));}catch(NumberFormatException e){System.out.println("숫자를 입력하세요.");}} public double number(String label,double min){while(true)try{double v=Double.parseDouble(text(label));if(v<min)throw new NumberFormatException();return v;}catch(NumberFormatException e){System.out.println(min+" 이상의 숫자를 입력하세요.");}} public LocalDate date(String label){while(true)try{return LocalDate.parse(text(label+"(YYYY-MM-DD): "));}catch(Exception e){System.out.println("날짜 형식이 올바르지 않습니다.");}} public boolean yes(String label){System.out.print(label+" (y/N): ");return sc.nextLine().trim().equalsIgnoreCase("y");} }
